import org.w3c.dom.HTMLCanvasElement
import org.khronos.webgl.WebGLRenderingContext as GL
import org.khronos.webgl.Float32Array
import org.khronos.webgl.Uint32Array
import org.khronos.webgl.set
import vision.gears.webglmath.UniformProvider
import vision.gears.webglmath.Geometry
import vision.gears.webglmath.Vec3
import vision.gears.webglmath.Mat4
import kotlin.js.Date

class Scene (
  val gl : WebGL2RenderingContext) : UniformProvider("scene") {

  val vsTrafo = Shader(gl, GL.VERTEX_SHADER, "trafo-vs.glsl")
  val fsTextured = Shader(gl, GL.FRAGMENT_SHADER, "textured-fs.glsl")
  val fsEnvmapped = Shader(gl, GL.FRAGMENT_SHADER, "envmapped-fs.glsl")
  val fsMaxBlinn = Shader(gl, GL.FRAGMENT_SHADER, "maxblinn-fs.glsl")
  val texturedProgram = Program(gl, vsTrafo, fsTextured)
  val envmappedProgram = Program(gl, vsTrafo, fsEnvmapped)
  val maxBlinnProgram = Program(gl, vsTrafo, fsMaxBlinn)

  val vsQuad = Shader(gl, GL.VERTEX_SHADER, "quad-vs.glsl")
  val fsRaycast = Shader(gl, GL.FRAGMENT_SHADER, "raycast-fs.glsl")
  val fsSpheretrace = Shader(gl, GL.FRAGMENT_SHADER, "spheretrace-fs.glsl")

  val quadGeometry = TexturedQuadGeometry(gl)

  val raycastProgram = Program(gl, vsQuad, fsRaycast)
  val spheretraceProgram = Program(gl, vsQuad, fsSpheretrace)
  val raycastMaterial = Material(raycastProgram)
  val spheretraceMaterial = Material(spheretraceProgram)
  val skyCubeTexture = TextureCube(gl,
      "media/posx512.jpg", "media/negx512.jpg",
      "media/posy512.jpg", "media/negy512.jpg",
      "media/posz512.jpg", "media/negz512.jpg"
    )
  init {
    raycastMaterial["envTexture"]?.set( skyCubeTexture )
    spheretraceMaterial["envTexture"]?.set( skyCubeTexture )
    raycastMaterial["noiseTexture"]?.set( Texture2D(gl, "media/noise.png") )
  }
  val raycastMesh = Mesh(raycastMaterial, quadGeometry)
  val spheretraceMesh = Mesh(spheretraceMaterial, quadGeometry)

  val gameObjects = ArrayList<GameObject>()

  val lights = Array<Light>(1) { Light(it, *Program.all) }
  init{
    lights[0].position.set(-1.0f, 1.0f, -1.0f, 0.0f).normalize()
    lights[0].powerDensity.set(1.0f, 1.0f, 1.0f)
  }

  val camera = PerspectiveCamera(*Program.all)

  val timeAtFirstFrame = Date().getTime()
  var timeAtLastFrame =  timeAtFirstFrame

  init{
    gl.enable(GL.DEPTH_TEST)
    addComponentsAndGatherUniforms(*Program.all)
  }

  // --- 1) Scene osztály belsejébe (mezők) ---
  /** Atomi adatok (flat: x0,y0,z0, x1,y1,z1, ...), maximum 64 atom shader-side. */
  var atomCount: Int = 0
  private var atomPositionsFlat = Float32Array(0) // length = atomCount * 3
  private var atomColorsFlat = Float32Array(0)    // length = atomCount * 3

  // default shader paramok (állíthatóak)
  var sceneScaleUniform: Float = 1.0f
  var useSMinUniform: Int = 1
  var maxStepsUniform: Int = 128
  var hitEpsilonUniform: Float = 0.001f

  // --- 2) Molekula betöltő / beállító (hívható amikor vannak koordináták) ---
  fun setMolecule(positions: FloatArray, colors: FloatArray) {
    // biztonsági korlát: shader csak 64 atomot kezel a jelen GLSL-ben
    val maxAtoms = 64
    val inCount = (positions.size / 3).coerceAtMost(maxAtoms)
    atomCount = inCount
    atomPositionsFlat = Float32Array(atomCount * 3)
    atomColorsFlat = Float32Array(atomCount * 3)
    // copy only the allowed amount
    for (i in 0 until atomCount*3) {
      atomPositionsFlat.set(i, positions[i])
      atomColorsFlat.set(i,  colors[i])
    }

    // ha a UniformProvider-ed kényelmesen kezeli a tömböket, beállítjuk itt is
    // (ha nem létezik ilyen .set, akkor fallbackot csinálunk az update-ben)
    /*try {
      // UniformProvider-style setting (sok wrapper támogatja Float32Array-ral)
      spheretraceMaterial["atomCount"]?.set(atomCount)
      spheretraceMaterial["atomPos"]?.set( atomPositionsFlat )
      spheretraceMaterial["atomColor"]?.set( atomColorsFlat )
    } catch (e: Throwable) {
      // Ha nem támogatott, majd az update() fogja feltölteni raw WebGL hívással
      console.log("UniformProvider atom array .set nem támogatott: $e")
    }*/
  }

  fun resize(gl : WebGL2RenderingContext, canvas : HTMLCanvasElement) {
    gl.viewport(0, 0, canvas.width, canvas.height)
    camera.setAspectRatio(canvas.width.toFloat() / canvas.height.toFloat())
  }

  @Suppress("UNUSED_PARAMETER")
  fun update(gl : WebGL2RenderingContext, keysPressed : Set<String>) {

    /*val timeAtThisFrame = Date().getTime()
    val dt = (timeAtThisFrame - timeAtLastFrame).toFloat() / 1000.0f
    val t  = (timeAtThisFrame - timeAtFirstFrame).toFloat() / 1000.0f    
    timeAtLastFrame = timeAtThisFrame

    camera.move(dt, keysPressed)

    // clear the screen
    gl.clearColor(0.3f, 0.0f, 0.3f, 1.0f)
    gl.clearDepth(1.0f)
    gl.clear(GL.COLOR_BUFFER_BIT or GL.DEPTH_BUFFER_BIT)

    //gameObjects.forEach { it.move(t, dt, keysPressed, gameObjects) }
    //gameObjects.forEach { it.update() }

    raycastMesh.draw(camera, this)
    //gameObjects.forEach { it.draw( camera, *lights ) }
    */

    val timeAtThisFrame = Date().getTime()
    val dt = (timeAtThisFrame - timeAtLastFrame).toFloat() / 1000.0f
    val t = (timeAtThisFrame - timeAtFirstFrame).toFloat() / 1000.0f
    timeAtLastFrame = timeAtThisFrame

    camera.move(dt, keysPressed)

    gl.clearColor(0.3f, 0.0f, 0.3f, 1.0f)
    gl.clearDepth(1.0f)
    gl.clear(GL.COLOR_BUFFER_BIT or GL.DEPTH_BUFFER_BIT)

    // fractal / molecule animation
    val twistAmp = 0.6f * kotlin.math.sin(t * 0.35f).toFloat()

    // --- Uniformok ---
    spheretraceMaterial["time"]?.set(t)
    spheretraceMaterial["sceneScale"]?.set(sceneScaleUniform)
    spheretraceMaterial["twistAmp"]?.set(twistAmp)
    spheretraceMaterial["useSMin"]?.set(useSMinUniform.toFloat())
    spheretraceMaterial["maxSteps"]?.set(maxStepsUniform.toFloat())
    spheretraceMaterial["hitEpsilon"]?.set(hitEpsilonUniform)
    spheretraceMaterial["atomCount"]?.set(atomCount.toFloat())

    // --- Raw WebGL feltöltés atom tömbökhöz ---
    if (atomCount > 0) {
      val locPos = gl.getUniformLocation(spheretraceProgram.glProgram, "atomPos")
      val locCol = gl.getUniformLocation(spheretraceProgram.glProgram, "atomColor")
      if (locPos != null) gl.uniform3fv(locPos, atomPositionsFlat)
      if (locCol != null) gl.uniform3fv(locCol, atomColorsFlat)
    }

    // draw
    spheretraceMesh.draw(camera, this)

  }
}
